// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function testFuzz_property(address ownerAddress, address caller) public {
        vm.assume(ownerAddress != address(0));
        vm.assume(caller != ownerAddress);

        vm.prank(ownerAddress);
        c.initialize();

        vm.prank(caller);
        address reported = c.owner();

        assertTrue(reported == ownerAddress);
    }
}
